// Справочники стран/городов меняются раз в год, а не на каждый поиск.
// Кэшируем их в static data воркфлоу на 24 часа => 0 лишних запросов к Tourvisor при попадании в кэш.
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const TTL = 24 * 60 * 60 * 1000;
const fresh = sd.refsTs && (now - sd.refsTs < TTL)
  && Array.isArray(sd.countries) && sd.countries.length
  && Array.isArray(sd.departures) && sd.departures.length;
return [{ json: { needFetch: !fresh } }];

// Сохраняем справочники в кэш воркфлоу
const c = $('Get countries').first().json || {};
const d = $('Get departures').first().json || {};
const countries = (c.lists && c.lists.countries && c.lists.countries.country) || [];
const departures = (d.lists && d.lists.departures && d.lists.departures.departure) || [];
const sd = $getWorkflowStaticData('global');
if (countries.length) sd.countries = countries;
if (departures.length) sd.departures = departures;
if (countries.length && departures.length) sd.refsTs = Date.now();
return [{ json: { storedCountries: countries.length, storedDepartures: departures.length } }];

// Параметры от агента
const p = $('When Executed by Another Workflow').first().json;
const sd = $getWorkflowStaticData('global');
const countries = sd.countries || [];
const departures = sd.departures || [];

const norm = s => String(s||'').toLowerCase().replace(/ё/g,'е').trim();

const wantCountry = norm(p.country);
let countryId = null;
for (const c of countries) {
  const n = norm(c.name);
  if (n === wantCountry || n.includes(wantCountry) || (wantCountry && wantCountry.includes(n))) { countryId = c.id; break; }
}

const wantCity = norm(p.city_from || 'санкт-петербург');
let departureId = null;
for (const dep of departures) {
  const n = norm(dep.name);
  if (n === wantCity || n.includes(wantCity) || (wantCity && wantCity.includes(n))) { departureId = dep.id; break; }
}

if (!countryId || !departureId) {
  return [{ json: { error: true, results_text: 'Не удалось определить ' + (!countryId ? ('страну «' + (p.country||'') + '»') : ('город вылета «' + (p.city_from||'') + '»')) + ' в справочнике Tourvisor. Уточни у клиента формулировку.' } }];
}

const toRu = s => {
  const m = String(s||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return m ? `${m[3]}.${m[2]}.${m[1]}` : String(s||'');
};

const adults = Math.min(Math.max(parseInt(p.adults)||2,1),6);
const childAges = String(p.childs||'').split(/[,;\s]+/).map(x=>parseInt(x)).filter(x=>!isNaN(x)&&x>=0&&x<=17).slice(0,3);

const query = {
  authlogin: 'REPLACE_TOURVISOR_LOGIN',
  authpass: 'REPLACE_TOURVISOR_PASS',
  departure: departureId,
  country: countryId,
  datefrom: toRu(p.dateFrom),
  dateto: toRu(p.dateTo),
  nightsfrom: parseInt(p.nightsFrom)||7,
  nightsto: parseInt(p.nightsTo)||10,
  adults,
  child: childAges.length,
  format: 'json'
};
childAges.forEach((a,i)=>{ query['childage'+(i+1)] = a; });

return [{ json: { error: false, query } }];

const r = $json || {};
const rid = (r.result && r.result.requestid) || r.requestid || '';
if (!rid) {
  return [{ json: { error: true, results_text: 'Tourvisor не принял поиск (нет requestid). Проверь authlogin/authpass и параметры — либо сервис временно недоступен.' } }];
}
const auth = 'authlogin=REPLACE_TOURVISOR_LOGIN&authpass=REPLACE_TOURVISOR_PASS';
return [{ json: {
  error: false,
  requestid: rid,
  statusUrl: 'https://tourvisor.ru/xml/result.php?' + auth + '&requestid=' + rid + '&type=status&format=json',
  resultUrl: 'https://tourvisor.ru/xml/result.php?' + auth + '&requestid=' + rid + '&type=result&format=json'
} }];

const resp = $json || {};
const init = $('Init poll').first().json;
const status = (resp.data && resp.data.status) || resp.status || {};
const state = String(status.state || '').toLowerCase();
const progress = parseInt(status.progress) || 0;
const hotelsfound = parseInt(status.hotelsfound) || 0;

// Жёсткий потолок опросов: 8 итераций по 6с => ~50с максимум вместо прежних 2 минут
const CAP = 8;
// Ранний выход: поиск закончен ИЛИ прогресс 100% ИЛИ уже набралось достаточно отелей
const finished = state === 'finished' || progress >= 100 || hotelsfound >= 12 || $runIndex >= CAP;

return [{ json: {
  finished,
  state,
  progress,
  hotelsfound,
  statusUrl: init.statusUrl,
  resultUrl: init.resultUrl
} }];

const r = $json || {};
let hotels = (r.data && r.data.result && r.data.result.hotel) || (r.result && r.result.hotel) || [];
if (!Array.isArray(hotels)) hotels = [hotels].filter(Boolean);

if (!hotels.length) {
  return [{ json: { results_text: 'Поиск Tourvisor не дал вариантов по этим параметрам. Попробуй изменить даты/ночи или предложи клиенту передать запрос менеджеру.', count: 0 } }];
}

hotels.sort((a,b) => (parseInt(a.price)||9e9) - (parseInt(b.price)||9e9));
const top = hotels.slice(0,3);
const fmt = n => String(n||'').replace(/\B(?=(\d{3})+(?!\d))/g,' ');

const lines = top.map((h,i) => {
  let tours = (h.tours && h.tours.tour) || [];
  if (!Array.isArray(tours)) tours = [tours].filter(Boolean);
  tours.sort((a,b) => (parseInt(a.price)||9e9) - (parseInt(b.price)||9e9));
  const t = tours[0] || {};
  const link = h.fulldesclink || h.hotelurl || t.operatorlink || '';
  const parts = [
    `${i+1}. ${h.hotelname||'Отель'} ${h.hotelstars ? h.hotelstars+'*' : ''} — ${[h.countryname,h.regionname].filter(Boolean).join(', ')}`,
    `   Вылет: ${t.flydate||'?'}, ночей: ${t.nights||'?'}, питание: ${t.mealrussian||t.meal||'?'}`,
    `   Оператор: ${t.operatorname||'?'}, цена от ${fmt(t.price||h.price)} руб.`
  ];
  if (h.hotelrating) parts.push(`   Рейтинг отеля: ${h.hotelrating}`);
  if (link) parts.push(`   Карточка тура: ${link}`);
  return parts.join('\n');
});

const text = lines.join('\n\n') + '\n\n[Это конкретные туры из системы Tourvisor (90+ операторов). Финальную цену и наличие мест на дату вылета фиксирует менеджер при бронировании.]';
return [{ json: { results_text: text, count: hotels.length } }];
